import {parseBib,connections,validateWorkspace,normalizeDoi} from './core.js';
const $=s=>document.querySelector(s),NS='http://www.w3.org/2000/svg',KEY='atlas-library-v1';
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let state={version:1,papers:[],manual:[]},edges=[],selected=null,hovered=null,positions=new Map(),nodeEls=new Map(),edgeEls=[],projected=new Map();
let camera={yaw:0,pitch:-.12,zoom:1},focus={x:0,y:0},drag=null,lastFrame=0,noticeTimer,busy=false,revision=0,summaryGeneration=0;
function html(tag,attrs={},text){const n=document.createElement(tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n}
function svg(tag,attrs={},text){const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n}
function firstAuthor(p){const author=(p.authors||'').split(/\s+and\s+/i)[0].trim();return author.includes(',')?author.split(',')[0].trim():author.split(/\s+/).pop()||p.id}
function notice(text){clearTimeout(noticeTimer);$('#notice').textContent=text;$('#notice').hidden=!text;if(text)noticeTimer=setTimeout(()=>$('#notice').hidden=true,6500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{notice('No se pudo guardar. Exporta una copia para conservar tu biblioteca.')}}
function layout(){positions.clear();const count=state.papers.length;state.papers.forEach((p,i)=>{const y=1-2*(i+.5)/count,a=i*2.399963,r=Math.sqrt(1-y*y);positions.set(p.id,{x:Math.cos(a)*r*350,y:y*260,z:Math.sin(a)*r*300})});
 // A light spring relaxation gives related papers nearby positions in three dimensions.
 const degree=new Map(state.papers.map(p=>[p.id,0]));edges.forEach(e=>{degree.set(e.source,degree.get(e.source)+1);degree.set(e.target,degree.get(e.target)+1)});
 for(let step=0;step<45;step++){const shifts=new Map(state.papers.map(p=>[p.id,{x:0,y:0,z:0}]));for(const e of edges){const a=positions.get(e.source),b=positions.get(e.target),sa=shifts.get(e.source),sb=shifts.get(e.target);const dx=b.x-a.x,dy=b.y-a.y,dz=b.z-a.z,len=Math.hypot(dx,dy,dz)||1,strength=(len-185)*.003/Math.sqrt(Math.max(degree.get(e.source),degree.get(e.target),1));for(const [key,d]of [['x',dx],['y',dy],['z',dz]]){sa[key]+=d/len*strength*10;sb[key]-=d/len*strength*10}}
 for(const p of state.papers){const a=positions.get(p.id),s=shifts.get(p.id);a.x+=s.x;a.y+=s.y;a.z+=s.z}}
}
function rebuild(resetLayout=false){edges=connections(state.papers,state.manual);if(resetLayout||positions.size!==state.papers.length)layout();$('#empty').hidden=!!state.papers.length;$('#nodeLayer').replaceChildren();$('#edgeLayer').replaceChildren();nodeEls.clear();edgeEls=[];
 for(const edge of edges){const line=svg('line',{class:'edge '+edge.type,'aria-label':edge.reason});if(edge.type==='manual')line.setAttribute('stroke-dasharray','5 5');line.append(svg('title',{},edge.reason));line.onclick=e=>{e.stopPropagation();select(edge.source);notice(edge.reason)};$('#edgeLayer').append(line);edgeEls.push({edge,line})}
 for(const p of state.papers){const g=svg('g',{class:'node',tabindex:0,role:'button','aria-label':p.title,'data-id':p.id});g.append(svg('circle',{class:'halo',r:65,fill:'url(#halo)'}),svg('circle',{class:'pulse',r:21}),svg('circle',{class:'sphere',r:14,fill:'url(#orb)'}),svg('circle',{class:'hit-target',r:27,fill:'transparent'}));const label=svg('text',{class:'node-label','text-anchor':'middle',y:43},firstAuthor(p)+' · '+(p.year||''));g.append(label,svg('title',{},p.title));g.onpointerenter=()=>{hovered=p.id;highlight()};g.onpointerleave=()=>{hovered=null;highlight()};g.onfocus=()=>{hovered=p.id;highlight()};g.onblur=()=>{hovered=null;highlight()};g.onpointerdown=e=>{e.stopPropagation()};g.onclick=e=>{e.stopPropagation();select(p.id)};g.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();select(p.id)}};$('#nodeLayer').append(g);nodeEls.set(p.id,g)}highlight();paint(1)}
function highlight(){const id=hovered??selected,neighbors=new Set();edges.forEach(e=>{if(e.source===id)neighbors.add(e.target);if(e.target===id)neighbors.add(e.source)});for(const [pid,g]of nodeEls){g.classList.toggle('selected',pid===selected);g.classList.toggle('hovered',pid===hovered);g.classList.toggle('neighbor',neighbors.has(pid));g.querySelector('.sphere').setAttribute('fill',pid===selected?'url(#orbActive)':'url(#orb)');g.dataset.dim=id&&pid!==id&&!neighbors.has(pid)?'1':'0'}for(const {edge,line}of edgeEls){const active=edge.source===id||edge.target===id;line.classList.toggle('active',active);line.dataset.active=active?'1':'0';line.dataset.dim=id&&!active?'1':'0';if(edge.type==='citation'&&active)line.setAttribute('marker-end','url(#arrow)');else line.removeAttribute('marker-end')}}
function project(pos){const cy=Math.cos(camera.yaw),sy=Math.sin(camera.yaw),cp=Math.cos(camera.pitch),sp=Math.sin(camera.pitch),x=pos.x*cy+pos.z*sy,z=pos.z*cy-pos.x*sy,y=pos.y*cp-z*sp,depth=pos.y*sp+z*cp,scale=790/(790-depth);return{x:x*scale*camera.zoom,y:y*scale*camera.zoom,z:depth,scale:scale*camera.zoom}}
function paint(dt){projected=new Map([...positions].map(([id,p])=>[id,project(p)]));const active=projected.get(selected);const target=active?{x:-active.x*.8,y:-active.y*.65}:{x:0,y:0};const ease=reduced?1:1-Math.exp(-dt*4);focus.x+=(target.x-focus.x)*ease;focus.y+=(target.y-focus.y)*ease;
 for(const [id,p]of projected){p.sx=600+p.x+focus.x;p.sy=345+p.y+focus.y;const g=nodeEls.get(id);const size=p.scale*(id===selected?1.6:1);g.setAttribute('transform',`translate(${p.sx} ${p.sy}) scale(${size})`);g.querySelector('.hit-target').setAttribute('r',Math.max(18,24/size));g.style.opacity=g.dataset.dim==='1'?.48:Math.max(.65,Math.min(1,(p.z+420)/650));}
 for(const {edge,line}of edgeEls){const a=projected.get(edge.source),b=projected.get(edge.target);line.setAttribute('x1',a.sx);line.setAttribute('y1',a.sy);line.setAttribute('x2',b.sx);line.setAttribute('y2',b.sy);line.setAttribute('stroke-opacity',line.dataset.dim==='1'?.035:line.dataset.active==='1'?.95:Math.max(.1,Math.min(.38,((a.z+b.z)/2+400)/1800)))}
 // Keep node elements attached: reparenting during animation interrupts pointer clicks and focus.
 if(selected)positionCard();}
function positionCard(){const p=projected.get(selected);if(!p)return;const graph=$('#graph'),wrap=$('.universe').getBoundingClientRect(),card=$('#card');const pt=graph.createSVGPoint();pt.x=p.sx;pt.y=p.sy;const screen=pt.matrixTransform(graph.getScreenCTM());let x=screen.x-wrap.left+42*p.scale,y=screen.y-wrap.top-35;
 if(innerWidth<650){x=(wrap.width-card.offsetWidth)/2;y=Math.max(12,wrap.height-card.offsetHeight-55)}else{if(x+card.offsetWidth>wrap.width-16)x=screen.x-wrap.left-card.offsetWidth-42*p.scale;y=Math.max(12,Math.min(y,wrap.height-card.offsetHeight-60))}card.style.left=Math.max(12,Math.min(x,wrap.width-card.offsetWidth-12))+'px';card.style.top=y+'px'}
function select(id){summaryGeneration++;selected=id;hovered=null;const p=state.papers.find(p=>p.id===id);$('#card').hidden=!p;if(p){$('#cardTitle').textContent=p.title;$('#summary').hidden=true;$('#summary').replaceChildren();$('#summarize').disabled=false;$('#summarize').textContent='Resumir artículo ↗';$('#card').getAnimations().forEach(a=>a.cancel());if(!reduced)$('#card').animate([{opacity:0,translate:'0 8px'},{opacity:1,translate:'0 0'}],{duration:350,easing:'ease-out'})}highlight();paint(1/60)}
function closeCard(){select(null)}$('#closeCard').onclick=closeCard;document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeCard();$('#graph').focus()}});
$('#graph').addEventListener('pointerdown',e=>{if(e.target.closest('.node,.edge'))return;drag={x:e.clientX,y:e.clientY,yaw:camera.yaw,pitch:camera.pitch,moved:false};$('#graph').setPointerCapture(e.pointerId)});$('#graph').addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>4)drag.moved=true;camera.yaw=drag.yaw+dx*.006;camera.pitch=Math.max(-1.3,Math.min(1.3,drag.pitch+dy*.004));if(reduced)paint(1)});$('#graph').addEventListener('pointerup',e=>{if(drag&&!drag.moved&&!e.target.closest('.edge,.node'))closeCard();drag=null});$('#graph').addEventListener('pointercancel',()=>drag=null);$('#graph').addEventListener('wheel',e=>{e.preventDefault();camera.zoom=Math.max(.45,Math.min(2.4,camera.zoom*Math.exp(-e.deltaY*.001)));if(reduced)paint(1)},{passive:false});$('#fit').onclick=()=>{camera={yaw:0,pitch:-.12,zoom:1};closeCard();if(reduced)paint(1)};
function animate(t){const dt=Math.min(.05,(t-lastFrame)/1000||.016);lastFrame=t;if(!reduced&&!selected&&!hovered&&!drag)camera.yaw+=dt*.045;if(!document.hidden&&state.papers.length)paint(dt);requestAnimationFrame(animate)}if(!reduced)requestAnimationFrame(animate);new ResizeObserver(()=>{if(state.papers.length)paint(1)}).observe($('.universe'));
function safeUrl(p){try{const u=new URL(p.doi?'https://doi.org/'+p.doi:p.url);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
async function fetchMetadata(p){if(!p.doi)return false;const res=await fetch('https://api.crossref.org/works/'+encodeURIComponent(normalizeDoi(p.doi)),{signal:AbortSignal.timeout(16000)});if(!res.ok)throw Error('Crossref no disponible');const {message:m}=await res.json();if(m.abstract){const doc=new DOMParser().parseFromString(m.abstract,'text/html');p.abstract=(doc.body.textContent||'').trim()}p.references=(m.reference??[]).map(r=>normalizeDoi(r.DOI??'')).filter(Boolean);p.lookup='ok';p.lookupDate=new Date().toISOString();return true}
// Extractive summary: retain original sentences rather than infer findings from a title.
function summarizeAbstract(text){const sentences=text.replace(/\s+/g,' ').trim().match(/[^.!?]+(?:[.!?]+(?:\s|$)|$)/g)?.map(s=>s.trim()).filter(Boolean)??[text];if(sentences.length<=4)return sentences.join(' ');const cues=/\b(show|found|demonstrat|result|conclud|suggest|reveal|here|we|report|identify|identified)\w*/i;const scored=sentences.map((s,i)=>({s,i,score:(i===0?3:0)+(i===sentences.length-1?2:0)+(cues.test(s)?2:0)}));return scored.sort((a,b)=>b.score-a.score).slice(0,3).sort((a,b)=>a.i-b.i).map(x=>x.s).join(' ')}
$('#summarize').onclick=async()=>{const p=state.papers.find(p=>p.id===selected);if(!p)return;const generation=++summaryGeneration,rev=revision;$('#summarize').disabled=true;$('#summarize').textContent='Preparando resumen…';const box=$('#summary');box.hidden=false;box.replaceChildren();try{if(!p.abstract&&p.doi){await fetchMetadata(p);if(rev===revision){save();rebuild()}}if(generation!==summaryGeneration||rev!==revision)return;if(p.abstract){box.append(html('small',{},'RESUMEN EXTRACTIVO DEL ABSTRACT'),html('p',{},summarizeAbstract(p.abstract)))}else box.append(html('p',{},'No hay un abstract disponible para resumir este artículo.'));const url=safeUrl(p);if(url)box.append(html('a',{href:url,target:'_blank',rel:'noopener noreferrer'},'Abrir artículo ↗'))}catch{if(generation===summaryGeneration){box.append(html('p',{},'No se pudo recuperar el texto. Inténtalo de nuevo.'));const url=safeUrl(p);if(url)box.append(html('a',{href:url,target:'_blank',rel:'noopener noreferrer'},'Abrir artículo ↗'))}}finally{if(generation===summaryGeneration){$('#summarize').disabled=false;$('#summarize').textContent='Resumir artículo ↗';positionCard()}}};
function replace(data,persist=true){revision++;summaryGeneration++;state=data;selected=null;hovered=null;camera={yaw:0,pitch:-.12,zoom:1};focus={x:0,y:0};$('#card').hidden=true;if(persist)save();rebuild(true)}
async function demo(){try{const res=await fetch('example.bib');if(!res.ok)throw Error();replace({version:1,papers:parseBib(await res.text()),manual:[]})}catch{notice('No se pudo cargar el ejemplo. Importa un fichero .bib.')}}$('#example').onclick=demo;
$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('El archivo supera 5 MB.');const text=await file.text(),data=file.name.toLowerCase().endsWith('.json')?validateWorkspace(JSON.parse(text)):{version:1,papers:parseBib(text),manual:[]};if(state.papers.length&&!confirm('¿Reemplazar la biblioteca actual? Exporta una copia si quieres conservarla.'))return;replace(data)}catch(error){notice(error.message)}finally{e.target.value=''}};
$('#export').onclick=()=>{if(!state.papers.length){notice('Importa una bibliografía primero.');return}const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));html('a',{href:url,download:'atlas-biblioteca.json'}).click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#enrich').onclick=async()=>{if(busy)return;const papers=state.papers.filter(p=>p.doi&&p.lookup!=='ok');if(!papers.length){notice('Metadatos actualizados.');return}busy=true;$('#enrich').disabled=true;$('#file').disabled=true;const rev=revision;let failed=0;try{for(let i=0;i<papers.length;i++){notice(`Actualizando ${i+1}/${papers.length}…`);try{await fetchMetadata(papers[i])}catch{papers[i].lookup='error';failed++}if(rev!==revision)break;save()}if(rev===revision)rebuild();notice(failed?`${failed} referencias sin metadatos disponibles.`:'Metadatos actualizados.')}finally{busy=false;$('#enrich').disabled=false;$('#file').disabled=false}};
try{const saved=localStorage.getItem(KEY);if(saved)replace(validateWorkspace(JSON.parse(saved)),false);else await demo()}catch{rebuild();notice('No se pudo recuperar la biblioteca. Importa una copia JSON.')}
